#include "kv_cached_attention_inference_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    KvCachedAttentionInferenceCustomTilingData tiling;

    // Shapes:
    // Q:      [B, q_len, d_model]
    // K/V:    [B, kv_len, d_model]
    const auto* qShape = context->GetInputShape(0);
    const auto* kShape = context->GetInputShape(1);
    if (qShape == nullptr || kShape == nullptr) {
        return ge::GRAPH_FAILED;
    }

    // Assume ND
    uint32_t rankQ = qShape->GetOriginShape().GetDimNum();
    uint32_t rankK = kShape->GetOriginShape().GetDimNum();
    if (rankQ < 2 || rankK < 2) {
        return ge::GRAPH_FAILED;
    }

    uint32_t batch    = (rankQ == 3) ? (uint32_t)qShape->GetOriginShape().GetDim(0) : 1U;
    uint32_t qLen     = (rankQ == 3) ? (uint32_t)qShape->GetOriginShape().GetDim(1) : 1U;
    uint32_t dModel   = (rankQ == 3) ? (uint32_t)qShape->GetOriginShape().GetDim(2) : (uint32_t)qShape->GetOriginShape().GetDim(1);
    uint32_t kvLen    = (rankK == 3) ? (uint32_t)kShape->GetOriginShape().GetDim(1) : (uint32_t)kShape->GetOriginShape().GetDim(0);

    // Set simple tiles (can be tuned)
    const uint32_t tileKv = 256;   // kv_len tile
    const uint32_t tileD  = 512;   // d_model tile

    // Reasonable block dim for small batches
    const uint32_t BLOCK_DIM = 8;

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_batch(batch);
    tiling.set_qLen(qLen);
    tiling.set_kvLen(kvLen);
    tiling.set_dModel(dModel);
    tiling.set_blockDim(BLOCK_DIM);
    tiling.set_tileKv(tileKv);
    tiling.set_tileD(tileD);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // No extra workspace required on host side
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // Output shape = Q shape
    const gert::Shape* qShape = context->GetInputShape(0);
    if (qShape == nullptr) {
        return GRAPH_FAILED;
    }
    gert::Shape* outShape = context->GetOutputShape(0);
    *outShape = *qShape;
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return GRAPH_SUCCESS;
}
